    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Uyanırken", "Bizi öldürdükten (uyuttuktan) sonra dirilten Allah'a hamd olsun; dönüş de yalnız O'nadır.", "Uykudan uyanır uyanmaz Allah'a şükretmek için okunur.", "Peygamber ﷺ uyanınca bunu okurdu — güne şükür ve ahiret hatırlatmasıyla başlamak."),
        "dua_leaving_home" to DuaText("Evden çıkarken", "Allah'ın adıyla, Allah'a tevekkül ettim; güç ve kuvvet ancak Allah'tandır.", "Evden çıkarken korunmak için okunur.", "Bu duayı okuyana 'hidayet buldun, kifayet edildin, korundun' denir ve şeytan ondan uzaklaşır."),
